select pg_temp.assert_true(to_regprocedure('public.begin_performance_review_mail(uuid,uuid,text)') is not null,'strict begin RPC exists');
set local role authenticated;
select pg_temp.expect_state('select public.begin_performance_review_mail(null,null,null)','42501');
reset role;
set local role anon;
select pg_temp.expect_state('select public.begin_performance_review_mail(null,null,null)','42501');
reset role;
set local role service_role;
select pg_temp.assert_true(public.begin_performance_review_mail(null,null,null) is false,'null inputs cannot authorize send');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,gen_random_uuid(),repeat('a',64)) is false,'wrong claim cannot authorize send');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'SHA') is false,'invalid SHA cannot authorize send');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,repeat('a',64)) is true,'one exact claim authorizes sending');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,repeat('a',64)) is false,'duplicate begin never authorizes send');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,repeat('b',64)) is false,'different attachment cannot retry');
reset role;
select pg_temp.assert_true((select state='sending' and attachment_sha256=repeat('a',64) and sending_at is not null from private.performance_review_mail_outbox),'sending state binds immutable attachment hash');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select pg_temp.assert_true(public.performance_review_workspace()->'reviews'->0=current_setting('test.submitted')::jsonb->'review','sending never changes employee DTO');
reset role;
